import React, { useState, useEffect } from 'react';

function App() {
  const [mekanlar, setMekanlar] = useState([]);

  useEffect(() => {
    // Backend sunucumuzdan verileri çekiyoruz
    fetch('http://localhost:5000/api/rota')
      .then(response => response.json())
      .then(data => setMekanlar(data))
      .catch(err => console.error("Veri çekme hatası:", err));
  }, []);

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial' }}>
      <h1>Antalya Rota Asistanı</h1>
      <div style={{ display: 'grid', gap: '10px' }}>
        {mekanlar.map(mekan => (
          <div key={mekan.id} style={{ border: '1px solid #ccc', padding: '10px', borderRadius: '8px' }}>
            <h3>{mekan.ad}</h3>
            <p>Kategori: {mekan.kategori}</p>
            <p>Süre: {mekan.sure} dk</p>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
